mapper.select:
SELECT id, calculation_id, source_system, source_fact_type, source_fact_id, tax_scope_key, origin, transaction_kind, tax_subject_party_id, currency, occurred_at, tax_point_date, tax_point_basis, registered_at, reporting_status, reporting_block_reason, source_payload_hash, create_time, update_time FROM t_tax_transaction
WHERE source_system = #{sourceSystem} AND source_fact_type = #{sourceFactType} AND source_fact_id = #{sourceFactId}
  AND tax_scope_key = #{taxScopeKey}
